------------ lifeCycle ------------

function UIBattleFlipCardDialog:__init()
    self:CleanProperties()
end

function UIBattleFlipCardDialog:__delete()
    self:CleanProperties()
end

function UIBattleFlipCardDialog:Awake()
end

function UIBattleFlipCardDialog:OnInitialize()
    xTry(function()
        local params = self.controller.Argument.parameters
        self.houseOwnerNeedFlip = checkNumber(params.mainNeedFlip) == 1
        self.houseOtherNeedFlip = checkNumber(params.subNeedFlip) == 1
        self.playerRewards = params.rewards
        self.rewardsList = params.rewardsList
        self.isHouseOwner = BattleInfo:IsInvited() == 0
        self:InitComponent()
        self:AddListener()
    end)
end

function UIBattleFlipCardDialog:OnShow()
    xTry(function()
        CoStart(function()
            CoYield(Yielders.GetWaitForSeconds(2))
            self.Anim_Root:Play(AnimShuffle)
            CoYield(Yielders.GetWaitForSeconds(1.25))
            self.Anim_TopNode:Play(AnimStartChoose)

            -- 房主选牌
            if self.houseOwnerNeedFlip then
                CoYield(self:PlayerChooseCard(1))
            end

            -- 房客选牌
            if self.houseOtherNeedFlip then
                CoYield(self:PlayerChooseCard(2))
            end

            -- 双方都选择完成
            self:SetCardsBackwardCanClickState(false)
            self.Txt_TiipsDesc.text = localize("点击空白处关闭")
            self.tc_chooseCountDown:Stop()
            self.Txt_CountDown.text = "0s"
            UIEventProxy.Create(self.RT_BtnClose.gameObject).onPointerClick = function()
                UIModule.BackDialog()
            end
        end)
    end)
end

