function UIBattleFlipCardDialog:CleanProperties()
    self.isHouseOwner = nil
    self.LT_PlayerHead = nil
    self.tc_chooseCountDown = nil
    self.tc_requestCountDown = nil
    self.eventChooseCardResponse = nil
    self.chooseCardResult = nil
    self.houseOwnerNeedFlip = nil
    self.houseOtherNeedFlip = nil
    self.playerRewards = nil
    self.rewardsList = nil
end

function UIBattleFlipCardDialog:AddListener()
    self.eventChooseCardResponse = Events.AddListener(Constants.EventNames.ChooseCardResponse, Bind(self, self.OnChooseCardConfirm))
end

function UIBattleFlipCardDialog:RemoveListener()
    Events.RemoveListener(Constants.EventNames.ChooseCardResponse, self.eventChooseCardResponse)
end

function UIBattleFlipCardDialog:InitComponent()
    self.LT_PlayerHead = GetLuaBehaviour(self.RT_PlayerHead.gameObject, "Game.Behaviours.CommonPlayerHeadNode").Env

    -- 选择卡牌的计时器
    ---@type TimeCoroutine
    self.tc_chooseCountDown = TimeCoroutine(2)
    self.tc_chooseCountDown:OnTimerCallback(function(timer)
        self.Txt_CountDown.text = string.format("%ds", TimeCountDownMax-timer)
    end)

    -- http请求选牌结果的计时器
    ---@type TimeCoroutine
    self.tc_requestCountDown = TimeCoroutine(2)

    self.chooseCardResult = {}

    -- 初始化所有卡牌
    self:InitCards()
end

--- 初始化所有卡牌
function UIBattleFlipCardDialog:InitCards()
    local childCount = self.RT_CardsRoot.childCount
    for i = 0, childCount - 1, 1 do
        local child = self.RT_CardsRoot:GetChild(i)
        if isNotNull(child) then
            local lb = GetLuaBehaviour(child.gameObject, CardLuaPath)
            lb.Env:SetPos(i + 1)
            lb.Env:SetReward(self.rewardsList[i+1]) -- 初始展示的奖励
            lb.Env:SetForwardCanClick(false)
            lb.Env:SetBackwardCanClick(false)
            lb.Env:SetBackwardOnClick(Bind(self, self.RequestChooseCard))
        end
    end
end

--- 设置所有卡牌背面是否可以点击
function UIBattleFlipCardDialog:SetCardsBackwardCanClickState(state)
    local childCount = self.RT_CardsRoot.childCount
    for i = 0, childCount - 1, 1 do
        local child = self.RT_CardsRoot:GetChild(i)
        if isNotNull(child) then
            local lb = GetLuaBehaviour(child.gameObject, CardLuaPath)
            lb.Env:SetBackwardCanClick(state)
        end
    end
end

function UIBattleFlipCardDialog:GetPlayerDesc(who)
    local playerDesc
    if who == 1 then
        if self.isHouseOwner then
            playerDesc = UIBattlePlayerInfoMgr:GetMyPlayerDesc()
        else
            playerDesc = UIBattlePlayerInfoMgr:GetOtherPlayerDesc()
        end
    else
        if self.isHouseOwner then
            playerDesc = UIBattlePlayerInfoMgr:GetOtherPlayerDesc()
        else
            playerDesc = UIBattlePlayerInfoMgr:GetMyPlayerDesc()
        end
    end
    return playerDesc
end

function UIBattleFlipCardDialog:GetPlayerChooseResult(who)
    local playerDesc = self:GetPlayerDesc(who)
    local playerId = playerDesc.playerId
    return self.chooseCardResult[playerId]
end

function UIBattleFlipCardDialog:DrawPlayerRewards(who)
    local playerDesc = self:GetPlayerDesc(who)
    local playerId = playerDesc.playerId
    local rewards = self.playerRewards[tostring(playerId)]
    
    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = DeepCopy(rewards) } })

    --剔除奖励中的体力，服务器会直接把体力奖励计算在response.hp字段中，这里再加就重复了
    for i = 1, #rewards, 1 do
        if checkNumber(rewards[i].goodsId) == Constants.Currency.HpId then
            table.remove(rewards, i)
            break
        end
    end

    GoodsUtils.DrawRewards(rewards, true)
end

--- 设置当前选牌玩家的头像
---@param who any
function UIBattleFlipCardDialog:SetPlayerHeadIcon(who)
    local playerDesc = self:GetPlayerDesc(who)
    local avatarId = checkInt(playerDesc.avatar)
    local avatarFrameId = checkInt(playerDesc.avatarFrame)
    self.LT_PlayerHead:FreshAvatarFrame(avatarId, avatarFrameId)
    KTool.SetActive(self.RT_PlayerHeadOwnerIcon, who == 1)
end

--- 展示玩家选择的结果
---@param who any
function UIBattleFlipCardDialog:ShowPlayerChoose(who)
    local pos = self:GetPlayerChooseResult(who)
    local child = self.RT_CardsRoot:GetChild(pos - 1)
    if isNotNull(child) then
        local playerDesc = self:GetPlayerDesc(who)
        local playerId = playerDesc.playerId
        local rewards = self.playerRewards[tostring(playerId)]

        if isNotNull(rewards) then
            local lb = GetLuaBehaviour(child.gameObject, CardLuaPath)
            lb.Env:ShowFlip(rewards[1], playerDesc, who)
        end
    end
end

--- 请求选牌
---@param pos any
function UIBattleFlipCardDialog:RequestChooseCard(pos)
    self:SetCardsBackwardCanClickState(false)
    local roomId = BattleViewMgr.roomId
    AppService:GetInstance():SendTcpData(Constants.Packets.ChooseCardRequest, {position = pos, roomId = roomId})
end

--- 选牌确认
---@param data any
function UIBattleFlipCardDialog:OnChooseCardConfirm(data)
    if checkNumber(data.result) ~= 0 then
        local msg = AnnihilationUtils.GetServerErrorMgr(checkNumber(data.result))
        GameUtils.Toast(msg)
        return
    end
    local playerId = checkNumber(data.playerId)
    local pos = data.position
    self.chooseCardResult[playerId] = pos
end

--- http请求选牌结果
function UIBattleFlipCardDialog:RequestChooseResult(who)
    local playerDesc = self:GetPlayerDesc(who)
    local playerId = playerDesc.playerId
    local roomId = BattleViewMgr.roomId
    GameUtils.Request(Interfaces.OverseaRegionalBossGetFlipResult, {roomId = roomId, flipPlayerId = playerId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local flipPosition = jsonData.flipPosition
        for playerId, pos in pairs(flipPosition) do
            self.chooseCardResult[checkNumber(playerId)] = pos
        end
    end)
end

--- 检查是否收到指定玩家的选牌结果
---@param who any
function UIBattleFlipCardDialog:IsPlayerChooseEnd(who)
    local playerDesc = self:GetPlayerDesc(who)
    local playerId = playerDesc.playerId
    return isNotNull(self.chooseCardResult[playerId])
end

--- 玩家选牌流程
---@param who any
function UIBattleFlipCardDialog:PlayerChooseCard(who)
    if who == 1 then
        -- 房主选牌
        if self.isHouseOwner then
            self:SetCardsBackwardCanClickState(true)
            self.Txt_TiipsDesc.text = localize("请选择一张卡牌")
        else
            self.Txt_TiipsDesc.text = localize("房主选择中...")
        end
    else
        -- 房客选牌
        if self.isHouseOwner then
            self.Txt_TiipsDesc.text = localize("房客选择中...")
        else
            self:SetCardsBackwardCanClickState(true)
            self.Txt_TiipsDesc.text = localize("请选择一张卡牌")
        end
    end
    
    self:SetPlayerHeadIcon(who)

    local timeOver = false
    self.tc_chooseCountDown:Stop()
    self.tc_chooseCountDown:Start(TimeCountDownMax, function()
        timeOver = true
        self:SetCardsBackwardCanClickState(false)
    end)

    local canRetry = true
    local retryTimes = 5

    -- 等待玩家选牌完成
    while not self:IsPlayerChooseEnd(who) do
        CoYield(Yielders.GetWaitForSeconds(0.1))
        if timeOver and canRetry and retryTimes > 0 then
            self:RequestChooseResult(who)
            canRetry = false
            self.tc_requestCountDown:Start(3, function()
                canRetry = true
                retryTimes = retryTimes - 1
            end)
        end
    end
    self.tc_requestCountDown:Stop()
    -- 关闭背面的点击
    self:SetCardsBackwardCanClickState(false)

    -- 展示玩家选择结果
    self:ShowPlayerChoose(who)
    CoYield(Yielders.GetWaitForSeconds(1))
    
    -- 打开奖励弹窗
    if self.isHouseOwner and (who == 1) then
        self:DrawPlayerRewards(1)
    end
    if (not self.isHouseOwner) and (who == 2) then
        self:DrawPlayerRewards(2)
    end
end

return UIBattleFlipCardDialog
